/**
 * WebGL2 Video Renderer
 * Renders video frames from ArrayBuffer to a canvas using WebGL2
 * Supports both RGBA and YUV420 formats
 *
 * YUV420 format reduces bandwidth by 62.5% compared to RGBA:
 * - RGBA: 4 bytes per pixel
 * - YUV420: 1.5 bytes per pixel (Y full resolution, U/V quarter resolution)
 * The YUV to RGB conversion is performed on the GPU via shader (nearly free)
 */
export class WebGLVideoRenderer {
    private canvas: HTMLCanvasElement;
    private gl: WebGL2RenderingContext;
    private texture: WebGLTexture | null = null;
    private program: WebGLProgram | null = null;
    private positionBuffer: WebGLBuffer | null = null;
    private texCoordBuffer: WebGLBuffer | null = null;

    // YUV420 support: three textures for Y, U, V planes
    private yuvProgram: WebGLProgram | null = null;
    private yTexture: WebGLTexture | null = null;
    private uTexture: WebGLTexture | null = null;
    private vTexture: WebGLTexture | null = null;

    private currentWidth: number = 0;
    private currentHeight: number = 0;
    private currentRotation: number = 0;
    private currentFormat: 'rgba' | 'yuv420' = 'rgba';
    private initialized: boolean = false;
    private _yuvRenderLogged: boolean = false;
    private videoAspectRatio: number = 16 / 9;

    constructor(canvas: HTMLCanvasElement) {
        this.canvas = canvas;

        // Prefer WebGL2 for PBO support (async texture uploads)
        const gl = canvas.getContext('webgl2', {
            alpha: false,
            antialias: false,
            depth: false,
            preserveDrawingBuffer: false,
            premultipliedAlpha: false,
        }) as WebGL2RenderingContext | null;

        if (!gl) {
            throw new Error('WebGL2 not supported');
        }

        this.gl = gl;
        console.log('[WebGL2] Context created');
        this.init();
    }

    private init(): void {
        const gl = this.gl;

        // Create shaders
        const vertexShaderSource = `
            attribute vec2 a_position;
            attribute vec2 a_texCoord;
            varying vec2 v_texCoord;

            void main() {
                gl_Position = vec4(a_position, 0.0, 1.0);
                v_texCoord = a_texCoord;
            }
        `;

        // RGBA fragment shader (direct passthrough)
        const fragmentShaderSource = `
            precision mediump float;
            uniform sampler2D u_texture;
            varying vec2 v_texCoord;

            void main() {
                gl_FragColor = texture2D(u_texture, v_texCoord);
            }
        `;

        // YUV420 to RGB fragment shader (BT.601 color space)
        // Y plane is full resolution, U and V planes are 1/4 resolution (half width, half height)
        // This shader converts YUV to RGB on the GPU for nearly free (parallel processing)
        const yuvFragmentShaderSource = `
            precision mediump float;
            uniform sampler2D u_textureY;
            uniform sampler2D u_textureU;
            uniform sampler2D u_textureV;
            varying vec2 v_texCoord;

            void main() {
                // Sample Y at full resolution
                float y = texture2D(u_textureY, v_texCoord).r;
                // Sample U and V (they are already at 1/4 resolution, but WebGL handles the scaling)
                float u = texture2D(u_textureU, v_texCoord).r - 0.5;
                float v = texture2D(u_textureV, v_texCoord).r - 0.5;

                // BT.601 YUV to RGB conversion matrix
                // R = Y + 1.402 * V
                // G = Y - 0.344 * U - 0.714 * V
                // B = Y + 1.772 * U
                float r = y + 1.402 * v;
                float g = y - 0.344 * u - 0.714 * v;
                float b = y + 1.772 * u;

                gl_FragColor = vec4(r, g, b, 1.0);
            }
        `;

        // Compile shaders
        const vertexShader = this.compileShader(gl.VERTEX_SHADER, vertexShaderSource);
        const fragmentShader = this.compileShader(gl.FRAGMENT_SHADER, fragmentShaderSource);

        if (!vertexShader || !fragmentShader) {
            throw new Error('Failed to compile shaders');
        }

        // Create program
        this.program = gl.createProgram();
        if (!this.program) {
            throw new Error('Failed to create WebGL program');
        }

        gl.attachShader(this.program, vertexShader);
        gl.attachShader(this.program, fragmentShader);
        gl.linkProgram(this.program);

        if (!gl.getProgramParameter(this.program, gl.LINK_STATUS)) {
            const error = gl.getProgramInfoLog(this.program);
            throw new Error(`Failed to link program: ${error}`);
        }

        gl.useProgram(this.program);

        // Create YUV420 shader program (compile and link separately)
        const yuvFragmentShader = this.compileShader(gl.FRAGMENT_SHADER, yuvFragmentShaderSource);
        if (yuvFragmentShader) {
            this.yuvProgram = gl.createProgram();
            if (this.yuvProgram) {
                // Reuse the same vertex shader
                const vertexShader2 = this.compileShader(gl.VERTEX_SHADER, vertexShaderSource);
                if (vertexShader2) {
                    gl.attachShader(this.yuvProgram, vertexShader2);
                    gl.attachShader(this.yuvProgram, yuvFragmentShader);
                    gl.linkProgram(this.yuvProgram);

                    if (!gl.getProgramParameter(this.yuvProgram, gl.LINK_STATUS)) {
                        console.warn('[WebGL2] Failed to link YUV program, falling back to RGBA only');
                        gl.deleteProgram(this.yuvProgram);
                        this.yuvProgram = null;
                    } else {
                        console.log('[WebGL2] YUV420 shader program initialized');
                    }
                }
            }
        }

        // Create YUV textures (even if program failed, for safety)
        this.yTexture = this.createLuminanceTexture();
        this.uTexture = this.createLuminanceTexture();
        this.vTexture = this.createLuminanceTexture();

        // Set up geometry (full-screen quad)
        const positions = new Float32Array([
            -1, -1,  // bottom-left
             1, -1,  // bottom-right
            -1,  1,  // top-left
             1,  1,  // top-right
        ]);

        const texCoords = new Float32Array([
            0, 1,  // bottom-left (Y flipped for OpenGL)
            1, 1,  // bottom-right
            0, 0,  // top-left
            1, 0,  // top-right
        ]);

        // Create position buffer
        this.positionBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, this.positionBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, positions, gl.STATIC_DRAW);

        const positionLocation = gl.getAttribLocation(this.program, 'a_position');
        gl.enableVertexAttribArray(positionLocation);
        gl.vertexAttribPointer(positionLocation, 2, gl.FLOAT, false, 0, 0);

        // Create texture coordinate buffer
        this.texCoordBuffer = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, this.texCoordBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, texCoords, gl.STATIC_DRAW);

        const texCoordLocation = gl.getAttribLocation(this.program, 'a_texCoord');
        gl.enableVertexAttribArray(texCoordLocation);
        gl.vertexAttribPointer(texCoordLocation, 2, gl.FLOAT, false, 0, 0);

        // Create texture
        this.texture = gl.createTexture();
        gl.bindTexture(gl.TEXTURE_2D, this.texture);

        // Set texture parameters
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);

        // Set viewport
        this.updateViewport();

        // Clear to black
        gl.clearColor(0, 0, 0, 1);
        gl.clear(gl.COLOR_BUFFER_BIT);

        this.initialized = true;
    }

    private compileShader(type: number, source: string): WebGLShader | null {
        const gl = this.gl;
        const shader = gl.createShader(type);

        if (!shader) {
            console.error('Failed to create shader');
            return null;
        }

        gl.shaderSource(shader, source);
        gl.compileShader(shader);

        if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
            const error = gl.getShaderInfoLog(shader);
            console.error(`Shader compilation error: ${error}`);
            gl.deleteShader(shader);
            return null;
        }

        return shader;
    }

    /**
     * Create a LUMINANCE texture for YUV planes (single channel)
     */
    private createLuminanceTexture(): WebGLTexture | null {
        const gl = this.gl;
        const texture = gl.createTexture();
        if (!texture) return null;

        gl.bindTexture(gl.TEXTURE_2D, texture);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);

        return texture;
    }

    public updateViewport(): void {
        // 使用 canvas 的實際尺寸（已由外部設置）
        // 如果未設置則嘗試使用 clientWidth/clientHeight
        let containerWidth = this.canvas.width;
        let containerHeight = this.canvas.height;

        // 如果 canvas.width/height 未設置，嘗試從 clientWidth/clientHeight 獲取
        if (containerWidth <= 0 || containerHeight <= 0) {
            containerWidth = this.canvas.clientWidth * window.devicePixelRatio || 1920;
            containerHeight = this.canvas.clientHeight * window.devicePixelRatio || 1080;
            this.canvas.width = containerWidth;
            this.canvas.height = containerHeight;
        }

        // Calculate viewport to maintain aspect ratio (letterbox/pillarbox)
        const containerAspect = containerWidth / containerHeight;

        let viewportWidth: number;
        let viewportHeight: number;
        let viewportX: number;
        let viewportY: number;

        if (containerAspect > this.videoAspectRatio) {
            // Container is wider than video - pillarbox (black bars on sides)
            viewportHeight = containerHeight;
            viewportWidth = containerHeight * this.videoAspectRatio;
            viewportX = (containerWidth - viewportWidth) / 2;
            viewportY = 0;
        } else {
            // Container is taller than video - letterbox (black bars on top/bottom)
            viewportWidth = containerWidth;
            viewportHeight = containerWidth / this.videoAspectRatio;
            viewportX = 0;
            viewportY = (containerHeight - viewportHeight) / 2;
        }

        this.gl.viewport(viewportX, viewportY, viewportWidth, viewportHeight);
    }

    public updateFrame(frameData: Uint8Array, width: number, height: number, rotation: number = 0): void {
        if (!this.initialized || !this.texture) {
            return;
        }

        const gl = this.gl;

        // Normalize rotation to 0, 90, 180, 270
        const normalizedRotation = ((rotation % 360) + 360) % 360;

        // Debug: log every frame's rotation (only first few times)
        if (this.currentWidth === 0 || normalizedRotation !== this.currentRotation) {
            console.log(`[WebGL2] updateFrame received: ${width}x${height}, rotation=${rotation}, normalized=${normalizedRotation}`);
        }

        // Check if we need to reallocate texture, update aspect ratio, or update rotation
        const needsUpdate = width !== this.currentWidth ||
                           height !== this.currentHeight ||
                           normalizedRotation !== this.currentRotation ||
                           this.currentFormat !== 'rgba';

        if (needsUpdate) {
            this.currentWidth = width;
            this.currentHeight = height;
            this.currentRotation = normalizedRotation;
            const wasYuv = this.currentFormat !== 'rgba';
            this.currentFormat = 'rgba';  // Track format switch

            // Always use the actual texture dimensions for aspect ratio
            // Rotation is handled by texture coordinates, not by changing the viewport
            this.videoAspectRatio = width / height;

            // Debug log
            const formatInfo = wasYuv ? ' (switched from YUV420 to RGBA)' : '';
            console.log(`[WebGL2] RGBA update: ${width}x${height}, rotation=${normalizedRotation}, aspectRatio=${this.videoAspectRatio.toFixed(3)}${formatInfo}`);

            // Update texture coordinates based on rotation
            this.updateTexCoords(normalizedRotation);

            // Bind texture
            gl.bindTexture(gl.TEXTURE_2D, this.texture);

            // Direct synchronous upload (PBO disabled for RGBA - no perf benefit in WebGL2)
            gl.texImage2D(
                gl.TEXTURE_2D,
                0,
                gl.RGBA,
                width,
                height,
                0,
                gl.RGBA,
                gl.UNSIGNED_BYTE,
                frameData
            );
        } else {
            // Bind texture
            gl.bindTexture(gl.TEXTURE_2D, this.texture);

            // Direct synchronous update
            gl.texSubImage2D(
                gl.TEXTURE_2D,
                0,
                0,
                0,
                width,
                height,
                gl.RGBA,
                gl.UNSIGNED_BYTE,
                frameData
            );
        }

        // Update viewport with correct aspect ratio
        this.updateViewport();

        // Render
        this.render();
    }

    /**
     * Update texture coordinates based on rotation angle
     * This rotates the texture to compensate for video rotation metadata
     *
     * Base texture coords (0°) with Y flip: (0,1), (1,1), (0,0), (1,0)
     * Vertex order: bottom-left, bottom-right, top-left, top-right
     *
     * Rotation metadata meaning:
     * - rotation=90: video was rotated 90° CW during recording
     * - rotation=270: video was rotated 270° CW (or 90° CCW) during recording
     * To display correctly, we apply the SAME rotation to the texture coordinates.
     */
    private updateTexCoords(rotation: number): void {
        const gl = this.gl;
        let texCoords: Float32Array;

        switch (rotation) {
            case 90:
                // Apply 90° CW rotation to texture coords
                texCoords = new Float32Array([
                    1, 1,  // bottom-left
                    1, 0,  // bottom-right
                    0, 1,  // top-left
                    0, 0,  // top-right
                ]);
                break;
            case 180:
                // Apply 180° rotation to texture coords
                texCoords = new Float32Array([
                    1, 0,  // bottom-left
                    0, 0,  // bottom-right
                    1, 1,  // top-left
                    0, 1,  // top-right
                ]);
                break;
            case 270:
                // Apply 270° CW (90° CCW) rotation to texture coords
                texCoords = new Float32Array([
                    1, 0,  // bottom-left
                    1, 1,  // bottom-right
                    0, 0,  // top-left
                    0, 1,  // top-right
                ]);
                break;
            default: // 0° or any other value
                // Normal orientation with Y flip
                texCoords = new Float32Array([
                    0, 1,  // bottom-left
                    1, 1,  // bottom-right
                    0, 0,  // top-left
                    1, 0,  // top-right
                ]);
                break;
        }

        // Update the texture coordinate buffer
        gl.bindBuffer(gl.ARRAY_BUFFER, this.texCoordBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, texCoords, gl.STATIC_DRAW);
    }

    public updateFrameFromBuffer(buffer: ArrayBuffer, width: number, height: number, rotation: number = 0, format: 'rgba' | 'yuv420' = 'rgba'): void {
        if (format === 'yuv420') {
            this.updateFrameYUV420(buffer, width, height, rotation);
        } else {
            const frameData = new Uint8Array(buffer);
            this.updateFrame(frameData, width, height, rotation);
        }
    }

    /**
     * Update frame with YUV420 data
     * YUV420 format: Y plane (width * height) + U plane (width/2 * height/2) + V plane (width/2 * height/2)
     * Total size: width * height * 1.5 bytes (62.5% smaller than RGBA)
     */
    private updateFrameYUV420(buffer: ArrayBuffer, width: number, height: number, rotation: number): void {
        if (!this.initialized || !this.yuvProgram || !this.yTexture || !this.uTexture || !this.vTexture) {
            console.warn('[WebGL2] YUV420 not available, this should not happen');
            return;
        }

        const gl = this.gl;
        const normalizedRotation = ((rotation % 360) + 360) % 360;

        // Calculate plane sizes
        const ySize = width * height;
        const uvWidth = Math.floor(width / 2);
        const uvHeight = Math.floor(height / 2);
        const uvSize = uvWidth * uvHeight;

        // Extract Y, U, V planes from buffer
        const data = new Uint8Array(buffer);
        const yPlane = data.subarray(0, ySize);
        const uPlane = data.subarray(ySize, ySize + uvSize);
        const vPlane = data.subarray(ySize + uvSize, ySize + uvSize * 2);

        // Check if we need to update dimensions/rotation
        const needsUpdate = width !== this.currentWidth ||
                           height !== this.currentHeight ||
                           normalizedRotation !== this.currentRotation ||
                           this.currentFormat !== 'yuv420';

        // CRITICAL: Set UNPACK_ALIGNMENT to 1 for LUMINANCE textures
        // Default is 4, which causes row alignment issues when width is not a multiple of 4
        // This is essential for YUV420 where each plane has 1 byte per pixel
        gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);

        if (needsUpdate) {
            this.currentWidth = width;
            this.currentHeight = height;
            this.currentRotation = normalizedRotation;
            this.currentFormat = 'yuv420';
            this.videoAspectRatio = width / height;

            console.log(`[WebGL2] YUV420 update: ${width}x${height}, rotation=${normalizedRotation}, buffer=${buffer.byteLength} bytes (saved ${((width * height * 4 - buffer.byteLength) / 1024 / 1024).toFixed(2)} MB)`);

            // Update texture coordinates for rotation
            this.updateTexCoords(normalizedRotation);

            // Upload Y plane
            gl.bindTexture(gl.TEXTURE_2D, this.yTexture);
            gl.texImage2D(gl.TEXTURE_2D, 0, gl.LUMINANCE, width, height, 0, gl.LUMINANCE, gl.UNSIGNED_BYTE, yPlane);

            // Upload U plane
            gl.bindTexture(gl.TEXTURE_2D, this.uTexture);
            gl.texImage2D(gl.TEXTURE_2D, 0, gl.LUMINANCE, uvWidth, uvHeight, 0, gl.LUMINANCE, gl.UNSIGNED_BYTE, uPlane);

            // Upload V plane
            gl.bindTexture(gl.TEXTURE_2D, this.vTexture);
            gl.texImage2D(gl.TEXTURE_2D, 0, gl.LUMINANCE, uvWidth, uvHeight, 0, gl.LUMINANCE, gl.UNSIGNED_BYTE, vPlane);
        } else {
            // Update Y plane
            gl.bindTexture(gl.TEXTURE_2D, this.yTexture);
            gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, width, height, gl.LUMINANCE, gl.UNSIGNED_BYTE, yPlane);

            // Update U plane
            gl.bindTexture(gl.TEXTURE_2D, this.uTexture);
            gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, uvWidth, uvHeight, gl.LUMINANCE, gl.UNSIGNED_BYTE, uPlane);

            // Update V plane
            gl.bindTexture(gl.TEXTURE_2D, this.vTexture);
            gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, uvWidth, uvHeight, gl.LUMINANCE, gl.UNSIGNED_BYTE, vPlane);
        }

        // Restore default UNPACK_ALIGNMENT for RGBA textures
        gl.pixelStorei(gl.UNPACK_ALIGNMENT, 4);

        // Update viewport and render
        this.updateViewport();
        this.renderYUV();
    }

    /**
     * Render using YUV420 shader program
     */
    private renderYUV(): void {
        const gl = this.gl;

        if (!this.yuvProgram) {
            console.error('[WebGL2] renderYUV called but yuvProgram is null');
            return;
        }

        // Debug: log canvas dimensions on first render
        if (!this._yuvRenderLogged) {
            console.log(`[WebGL2] renderYUV: canvas=${this.canvas.width}x${this.canvas.height}, video=${this.currentWidth}x${this.currentHeight}`);
            this._yuvRenderLogged = true;
        }

        // Clear entire canvas first
        gl.viewport(0, 0, this.canvas.width, this.canvas.height);
        gl.clearColor(0, 0, 0, 1);
        gl.clear(gl.COLOR_BUFFER_BIT);

        // Use YUV shader program
        gl.useProgram(this.yuvProgram);

        // Set up vertex attributes for YUV program
        const positionLocation = gl.getAttribLocation(this.yuvProgram, 'a_position');
        const texCoordLocation = gl.getAttribLocation(this.yuvProgram, 'a_texCoord');

        gl.bindBuffer(gl.ARRAY_BUFFER, this.positionBuffer);
        gl.enableVertexAttribArray(positionLocation);
        gl.vertexAttribPointer(positionLocation, 2, gl.FLOAT, false, 0, 0);

        gl.bindBuffer(gl.ARRAY_BUFFER, this.texCoordBuffer);
        gl.enableVertexAttribArray(texCoordLocation);
        gl.vertexAttribPointer(texCoordLocation, 2, gl.FLOAT, false, 0, 0);

        // Bind Y texture to texture unit 0
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, this.yTexture);
        gl.uniform1i(gl.getUniformLocation(this.yuvProgram, 'u_textureY'), 0);

        // Bind U texture to texture unit 1
        gl.activeTexture(gl.TEXTURE1);
        gl.bindTexture(gl.TEXTURE_2D, this.uTexture);
        gl.uniform1i(gl.getUniformLocation(this.yuvProgram, 'u_textureU'), 1);

        // Bind V texture to texture unit 2
        gl.activeTexture(gl.TEXTURE2);
        gl.bindTexture(gl.TEXTURE_2D, this.vTexture);
        gl.uniform1i(gl.getUniformLocation(this.yuvProgram, 'u_textureV'), 2);

        // Set viewport for video (maintains aspect ratio)
        this.updateViewport();

        // Draw
        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

        // Debug: check for WebGL errors
        const error = gl.getError();
        if (error !== gl.NO_ERROR) {
            console.error(`[WebGL2] renderYUV error: ${error}`);
        }

        // Reset to RGBA program for next RGBA frame (if any)
        // gl.useProgram(this.program);
    }

    private render(): void {
        const gl = this.gl;

        // Clear entire canvas first (for letterbox/pillarbox areas)
        gl.viewport(0, 0, this.canvas.width, this.canvas.height);
        gl.clearColor(0, 0, 0, 1);
        gl.clear(gl.COLOR_BUFFER_BIT);

        // CRITICAL: Ensure RGBA program is active (may have been switched to YUV program)
        gl.useProgram(this.program);

        // Set up vertex attributes for RGBA program (needed after switching from YUV)
        const positionLocation = gl.getAttribLocation(this.program!, 'a_position');
        const texCoordLocation = gl.getAttribLocation(this.program!, 'a_texCoord');

        gl.bindBuffer(gl.ARRAY_BUFFER, this.positionBuffer);
        gl.enableVertexAttribArray(positionLocation);
        gl.vertexAttribPointer(positionLocation, 2, gl.FLOAT, false, 0, 0);

        gl.bindBuffer(gl.ARRAY_BUFFER, this.texCoordBuffer);
        gl.enableVertexAttribArray(texCoordLocation);
        gl.vertexAttribPointer(texCoordLocation, 2, gl.FLOAT, false, 0, 0);

        // Bind RGBA texture to texture unit 0
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, this.texture);
        gl.uniform1i(gl.getUniformLocation(this.program!, 'u_texture'), 0);

        // Set viewport for video (maintains aspect ratio)
        this.updateViewport();

        // Draw video
        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    }

    public clear(): void {
        const gl = this.gl;
        gl.clearColor(0, 0, 0, 1);
        gl.clear(gl.COLOR_BUFFER_BIT);
    }

    /**
     * 重新渲染當前紋理（用於 canvas resize 時保持畫面）
     * 如果沒有有效紋理數據則不做任何事
     */
    public redraw(): void {
        // 沒有有效幀數據時不渲染
        if (this.currentWidth === 0 || this.currentHeight === 0) {
            return;
        }

        if (this.currentFormat === 'yuv420') {
            this.renderYUV();
        } else {
            this.render();
        }
    }

    /**
     * Reset internal state for new video loading
     * This ensures rotation and aspect ratio from previous video don't affect the new one
     */
    public resetState(): void {
        this.currentWidth = 0;
        this.currentHeight = 0;
        this.currentRotation = 0;
        this.currentFormat = 'rgba';
        this.videoAspectRatio = 16 / 9;

        // Reset texture coordinates to default (0° rotation)
        this.updateTexCoords(0);

        // Clear the canvas
        this.clear();

        console.log('[WebGL2] State reset for new video');
    }

    public destroy(): void {
        const gl = this.gl;

        // Clean up RGBA resources
        if (this.texture) {
            gl.deleteTexture(this.texture);
            this.texture = null;
        }

        if (this.positionBuffer) {
            gl.deleteBuffer(this.positionBuffer);
            this.positionBuffer = null;
        }

        if (this.texCoordBuffer) {
            gl.deleteBuffer(this.texCoordBuffer);
            this.texCoordBuffer = null;
        }

        if (this.program) {
            gl.deleteProgram(this.program);
            this.program = null;
        }

        // Clean up YUV resources
        if (this.yuvProgram) {
            gl.deleteProgram(this.yuvProgram);
            this.yuvProgram = null;
        }

        if (this.yTexture) {
            gl.deleteTexture(this.yTexture);
            this.yTexture = null;
        }

        if (this.uTexture) {
            gl.deleteTexture(this.uTexture);
            this.uTexture = null;
        }

        if (this.vTexture) {
            gl.deleteTexture(this.vTexture);
            this.vTexture = null;
        }

        this.initialized = false;
    }

    public isInitialized(): boolean {
        return this.initialized;
    }

    public getContext(): WebGL2RenderingContext {
        return this.gl;
    }
}
